function ensureState(v){const s=v.v33i1Equipment||(v.v33i1Equipment={});s.inventories=s.inventories&&typeof s.inventories==='object'?s.inventories:{};s.workOrders=Array.isArray(s.workOrders)?s.workOrders:[];s.stats=s.stats&&typeof s.stats==='object'?s.stats:freshStats();const d=freshStats();for(const[k,val]of Object.entries(d)){if(k==='resourceReserved'||k==='resourceRefunded'||k==='logisticsBlocked'||k==='producedByItem'||k==='migratedByItem'||k==='battleLostByItem'||k==='legacyUntrackedByItem'||k==='ruinHeldByItem'||k==='ruinTransferredOutByItem'||k==='ruinAcquiredByItem'){s.stats[k]=s.stats[k]&&typeof s.stats[k]==='object'?s.stats[k]:clone(val);for(const[ik,iv]of Object.entries(val))if(!Number.isFinite(Number(s.stats[k][ik])))s.stats[k][ik]=iv;}else if(!Number.isFinite(Number(s.stats[k])))s.stats[k]=val;}s.migrationDone=!!s.migrationDone;s.nextOrderId=Number(s.nextOrderId||1);return s;}
function ensurePerson(p){if(!p)return{weaponId:null,armorId:null};const e=p.militaryEquipment33I1||(p.militaryEquipment33I1={weaponId:null,armorId:null});if(!(e.weaponId==null||ITEMS[e.weaponId]?.slot==='weapon'))e.weaponId=null;if(!(e.armorId==null||ITEMS[e.armorId]?.slot==='armor'))e.armorId=null;return e;}
