function supplyNode(v,w,id){const t=w?.map?.get?.(Number(id));if(!t||Number(t.ownerId)!==Number(v.id))return false;const pop=(v.tileResidents?.(t.id)||[]).filter(p=>p.alive).length;return Number(t.id)===Number(v.coreTileId)||pop>0||buildingsAt(t,'barracks')>0||buildingsAt(t,'armory')>0;}
function capacityAt(v,w,id){const t=w?.map?.get?.(Number(id));if(!t||Number(t.ownerId)!==Number(v.id))return 0;const base=supplyNode(v,w,id)?6:0;return base+buildingsAt(t,'barracks')*12+buildingsAt(t,'armory')*72;}
function inventory(v,id){const s=ensureState(v),k=String(Number(id));const o=s.inventories[k]||(s.inventories[k]={});for(const itemId of Object.keys(ITEMS))if(itemId!=='improvised_club'&&!Number.isFinite(Number(o[itemId])))o[itemId]=0;return o;}
