function operationalTile(v,w,p){const f=formationForPerson(v,w,p);if(f&&Number.isFinite(Number(f.tileId)))return Number(f.tileId);const c=cohort(v,p?.militaryCohortId32A);if(c&&Number.isFinite(Number(c.tileId)))return Number(c.tileId);if(Number.isFinite(Number(p?.homeTileId)))return Number(p.homeTileId);return Number(v.coreTileId);}
