function coverage(v,w){const ps=activePeople(v),n=ps.length;if(!n)return{formalWeaponCoverage:0,armorCoverage:0,compatCoverage:0,clubFallback:0,active:0};let weapons=0,armor=0,clubs=0;for(const p of ps){const e=ensurePerson(p);if(e.weaponId&&ITEMS[e.weaponId]?.formal)weapons++;else clubs++;if(e.armorId&&ITEMS[e.armorId]?.slot==='armor')armor++;}const wc=weapons/n*100,ac=armor/n*100;return{formalWeaponCoverage:+wc.toFixed(1),armorCoverage:+ac.toFixed(1),compatCoverage:+clamp(wc*.65+ac*.35,0,100).toFixed(1),clubFallback:clubs,active:n};}
