function temporaryWorkerCandidate(v,w,item,tileId,exclude=new Set()){let best=null;for(const p of v.residents||[]){if(!civilianCraftEligible(p)||exclude.has(String(p.id))||p._v25CycleTask)continue;const home=Number(p.homeTileId),work=Number(p.workTileId??p.homeTileId),d=Math.min(w.map.distance(home,Number(tileId)),w.map.distance(work,Number(tileId)));if(!Number.isFinite(d))continue;const limit=item.workClass==='smithy'?2:3;if(d>limit)continue;let score=d*10;if(p.job==='목수')score-=item.workClass==='craft_bow'?8:3;if(p.job==='건축가'&&item.workClass==='craft')score-=2;if(p.job==='철공'&&item.workClass==='smithy')score-=8;if(!best||score<best.score)best={p,score};}return best?.p||null;}
