function reserveRecipe(v,w,item,tileId){const need=item.recipe||{};for(const[k,q]of Object.entries(need))if(availableResource(v,k)+1e-9<Number(q||0))return null;const got={};for(const[k,q0]of Object.entries(need)){const q=Number(q0||0);if(q<=0)continue;const x=Number(v.withdrawNetwork?.(k,q,tileId)??v.withdrawAt?.(tileId,k,q)??0);got[k]=x;if(x+1e-9<q){for(const[r,amt]of Object.entries(got))if(amt>0)v.depositAt?.(tileId,r,amt);return null;}}const st=ensureState(v).stats;for(const[k,x]of Object.entries(got))st.resourceReserved[k]=Number(st.resourceReserved[k]||0)+Number(x||0);return got;}
