NS.Telemetry.prototype.toJSON=function(w){const d=jsonPrev.call(this,w);d.version=VERSION;Object.assign(d.worldSummary||{},{v33I1Revision:'person-equipment-military-inventory-foundation-i1',v33I1ARevision:'equipment-logistics-military-craft-access-fix-i1a',equipmentRegistry33I1:'Person equipment slots weapon/armor backed by a data registry; future slots remain extensible.',equipmentInventory33I1:'Physical integer equipment is stored at settlement/supply-node inventories; base 6, Barracks +12, Armory +72 item slots.',equipmentProduction33I1:'Equipment Work Orders reserve real resources and consume real Person labor; smithy/craft workers forgo their normal production while assigned.',equipmentDistribution33I1:'Active Persons rearm only while physically present at an owned supply node; old gear is returned to local inventory.',equipmentCompatibility33I1:'H2 combat formula remains active through I1A1. Cohort equipment = 65% formal-weapon coverage + 35% armor coverage. Item quality stats are reserved for I2.',equipmentMigration33I1:'Legacy H2 generic equipment stock migrates deterministically into paired legacy weapon/armor kits; fresh worlds never produce legacy items.',equipmentLoss33I1:'I1A1 activates explicit battlefield recovery/loss for battle deaths. Wounded Persons keep their equipment; ordinary demobilization/non-battle death still returns gear through the existing lifecycle.',equipmentLogistics33I1A:'All nations have low-capacity short-range equipment redistribution; Armories extend range and raise each 30-day military logistics pulse to six physical items, including outbound supply to demand nodes.',temporaryMilitaryCraft33I1A:'Severe equipment demand can temporarily assign real civilian adults to military Work Orders. Smithy remains mandatory for iron equipment; temporary workers sacrifice their normal Person work cycle.',strandedWeaponDiagnostic33I1A:'Telemetry distinguishes national weapon stock from active club fallback through stranded-weapon demand diagnostics.',v33I1A1Revision:REV,battlefieldRecovery33I1A1:'Battle-death equipment is detached before Person removal, resolved as recovered or officially lost, and recovered field gear stays in a Formation recovery cache until an owned supply node is reached.',battlefieldRecoveryRates33I1A1:'ongoing round winner 85%, ongoing round loser 55%, unresolved 65%; engagement-ending loser 35%, deep-recovery loser 20%. Weapon and armor resolve independently.',equipmentConservation33I1A1:'produced + migrated = inventory + equipped + recovery cache + official battlefield loss + legacy pre-I1A1 untracked deficit; only unexplained residuals are errors.',legacyEquipmentReconciliation33I1A1:'positive pre-I1A1 ledger deficits are recorded once as legacyUntrackedLoss instead of being retroactively re-rolled as battlefield loss.',i1CombatScope:'OPENING/CONTACT/MELEE, reach, screen, penetration and protection are intentionally disabled until I2.'});return d;};

function countText(counts,slot){return Object.entries(counts).filter(([id,n])=>n>0&&ITEMS[id]?.slot===slot).sort((a,b)=>Number(ITEMS[b[0]]?.tier||0)-Number(ITEMS[a[0]]?.tier||0)).map(([id,n])=>`${ITEMS[id]?.label||id} ${n}`).join(' · ')||'-';}
function militaryPanel(ui){const root=ui?.q?.('villageContent'),w=ui?.world,v=w?.selectedNation;if(!root||!v||ui.sub!=='military')return;root.querySelectorAll('.v33i1-equipment-panel').forEach(x=>x.remove());const x=summary(v,w),activeComp=equipmentComposition(activePeople(v)),box=document.createElement('div');box.className='v33i1-equipment-panel';box.innerHTML=`<div class="section-head"><div><strong>🗡 I1A1 실제 군사 장비</strong><div class="small muted">Person별 weapon/armor · 지역 군수 이동 · 임시 군수 제작 · 품질 전투효과는 I2에서 활성화</div></div><span class="tag">호환 장비 ${x.compatCoverage.toFixed(0)}%</span></div><div class="v33i1-grid"><span>정식 무기 <b>${x.formalWeaponCoverage.toFixed(0)}%</b></span><span>갑옷 <b>${x.armorCoverage.toFixed(0)}%</b></span><span>곤봉 fallback <b>${x.clubFallback}명</b></span><span>재고 <b>${x.inventoryItems}/${x.inventoryCapacity}</b></span><span>제작 중 <b>${x.workOrders}</b></span><span>고립 무기수요 <b>${x.equipmentStrandedWeapons33I1A}</b></span><span>임시 제작자 <b>${x.temporaryMilitaryCrafters33I1A}</b></span><span>회수품 cache <b>${x.equipmentRecoveryCache33I1A1}</b></span><span>전장 유실 <b>${x.equipmentBattleLost33I1A1}</b></span><span>보존 오류 <b>${x.equipmentConservationErrors33I1A1}</b></span></div><div class="small"><b>현역 무기</b> ${esc(activeComp.weapon)}</div><div class="small"><b>현역 갑옷</b> ${esc(activeComp.armor)}</div><div class="small muted"><b>재고 무기</b> ${esc(countText(x.inventory,'weapon'))}<br><b>재고 갑옷</b> ${esc(countText(x.inventory,'armor'))}</div><div class="small muted" style="margin-top:5px">누적 제작 ${x.equipmentProduced33I1} · 지급 ${x.equipmentIssued33I1} · 회수 ${x.equipmentReturned33I1} · 재장비 ${x.equipmentReequipped33I1} · 물류 ${x.equipmentLogisticsItems33I1A} item · 전장 회수 ${x.equipmentBattleRecovered33I1A1} · 유실 ${x.equipmentBattleLost33I1A1} · legacy 결손 ${x.legacyUntrackedLoss33I1A1} · legacy kit ${x.legacyKitsMigrated33I1}</div>`;root.insertAdjacentElement('afterbegin',box);}
function tileEquipmentLines(ui){const root=ui?.q?.('tileInspector'),w=ui?.world,t=w?.map?.get?.(w?.selectedTileId);if(!root||!w||!t)return;const host=root.querySelector('.v33h2-formation-tile');if(!host)return;host.querySelectorAll('.v33i1-form-equip').forEach(x=>x.remove());const rows=(NS.V033H2?.allFormationSnapshots?.(w)||NS.V033H?.allFormationSnapshots?.(w)||[]).filter(x=>Number(x.f.tileId)===Number(t.id));const cards=[...host.querySelectorAll('.v33h-detail')];rows.forEach((r,i)=>{const ps=(NS.V033E1?.formationPeople?.(r.v,r.f)||[]).filter(p=>p.alive&&p.militaryStatus32A==='active'),c=equipmentComposition(ps),card=cards[i];if(card)card.insertAdjacentHTML('beforeend',`<div class="small muted v33i1-form-equip">장비 · 무기 ${esc(c.weapon)} · 갑옷 ${esc(c.armor)}</div>`);});}
if(NS.UI){const setPrev=NS.UI.prototype.setWorld,contentPrev=NS.UI.prototype.renderVillageContent,tilePrev=NS.UI.prototype.renderTile,headPrev=NS.UI.prototype.renderHeader;NS.UI.prototype.setWorld=function(w){return setPrev.call(this,attach(w));};NS.UI.prototype.renderVillageContent=function(){const r=contentPrev.call(this);militaryPanel(this);return r;};NS.UI.prototype.renderTile=function(){const r=tilePrev.call(this);tileEquipmentLines(this);return r;};NS.UI.prototype.renderHeader=function(){headPrev.call(this);document.title='Village Observer V0.33I1A1';const b=this.q?.('versionBadge')||document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33I1A1</strong>';const st=this.q?.('runtimeStatus');if(st)st.textContent='✓ V0.33I1A1 Battlefield Equipment Recovery + Loss';};}
if(typeof document!=='undefined'){const st=document.createElement('style');st.textContent=`.v33i1-equipment-panel{margin:0 0 10px;padding:10px;border:1px solid rgba(223,173,87,.28);border-radius:10px;background:rgba(42,29,12,.28)}.v33i1-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px 8px;margin:7px 0}.v33i1-grid span{padding:5px 7px;border-radius:7px;background:rgba(255,255,255,.035);font-size:10px}@media(max-width:620px){.v33i1-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}`;document.head.appendChild(st);}

if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33I1A1'))NS.PATCH_NOTES.unshift({version:'V0.33I1A1',date:'2026-10-08',title:'Battlefield Equipment Recovery + Loss',summary:'I1A 자연전쟁에서 전사자의 장비가 보존 ledger에서 아무 기록 없이 사라지던 경로를 정식 전장 회수·유실 lifecycle로 바꿉니다. 회수품은 부대가 운반해 자국 supply node에 입고되며, 회수 실패·전멸 시 유실은 공식 sink로 기록됩니다.',sections:[['전사자 장비',['BATTLE33 전사 확정 시 Person 제거 전에 weapon/armor를 분리해 전장 회수 판정 대상으로 넘깁니다.','진행 중 라운드는 승리측 85%, 패배측 55%, 불명확 65%를 사용하고, Engagement가 끝나는 패배측은 정상 후퇴 35%, DEEP_RECOVERY 20%를 사용합니다. 무기와 갑옷은 각각 독립 판정합니다.']],['Formation 회수품',['회수 성공 장비는 즉시 수도/창고로 순간이동하지 않고 해당 Formation의 field recovery cache에 남습니다.','부대가 자국 supply node에 도착하면 cache가 실제 지역 inventory로 입고됩니다. 운반 인원이 전시에 완전히 사라지면 BATTLEFIELD_ABANDONED로 공식 유실됩니다.']],['부상·호환',['전상자는 살아 있으므로 장비를 계속 보유합니다. 일반 동원해제와 비전투 사망은 기존 회수 경로를 유지합니다.','I1/I1A save의 기존 양(+) ledger 결손은 장비를 새로 생성하거나 임의의 회수 확률을 소급하지 않고 legacyUntrackedLoss로 1회 분리 기록합니다.']],['보존식',['생산+migration = 지역 재고+Person 장착+Formation recovery cache+공식 전장 유실+legacy 미추적 결손으로 감시합니다.','OPENING/CONTACT/MELEE, Reach, Screen, Penetration/Protection, 노획·내구도는 여전히 I2 또는 이후 범위입니다.']]]});
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33I1A'))NS.PATCH_NOTES.unshift({version:'V0.33I1A',date:'2026-10-07',title:'Equipment Logistics + Military Craft Access Fix',summary:'I1 자연주행에서 확인된 장비 고립과 제작 인력 접근 병목을 수정합니다. Armory가 없어도 저용량 근거리 군수 이동이 가능하고, Armory는 광역·대량 양방향 군수 허브가 됩니다. 장비 부족 시 실제 민간 Person을 임시 군수 제작에 투입할 수 있습니다.',sections:[['군수 물류',['Armory가 없어도 30일 pulse마다 최대 2개 장비를 근거리 supply node 사이에서 이동합니다.','Armory가 있으면 pulse 최대 6개, 더 넓은 경로를 사용하며 생산지/지역 재고를 모으는 것뿐 아니라 현역이 있는 supply node로 다시 내보냅니다.','현역의 weapon/armor deficit와 기존 군사 우선순위가 장비 수송 목적지를 결정합니다.']],['임시 군수 제작',['곤봉 사용자가 남거나 정식 무기 보급률이 낮으면 무기 생산을 갑옷·고급 업그레이드보다 우선합니다.','기초 장비는 적합한 일반 성인도 임시 제작할 수 있고, 활은 비전문가 대체 제작이 가능하지만 효율이 낮습니다.','철제 장비는 Smithy가 반드시 필요하지만 기존 철공 직업이 없어도 인근 성인 Person을 임시 배정할 수 있습니다. 임시 제작자는 해당 cycle의 기존 민간 생산을 포기합니다.']],['관측',['weapon/armor demand, stranded weapon, 실제 물류 item 수, 임시 제작자, PATH/RANGE/CAPACITY/NO_STOCK blocker를 telemetry/CSV에 추가합니다.','기존 I1 conservation invariant와 Person별 장비/정수 재고는 그대로 유지합니다.']],['범위',['저장용량 자체는 0.34 Settlement 구조 전환 전까지 유지합니다.','H2 호환 Combat Power와 I1의 65% weapon + 35% armor bridge를 유지하며 무기 품질/OPENING/CONTACT/MELEE는 I2로 넘깁니다.']]]});
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33I1'))NS.PATCH_NOTES.unshift({version:'V0.33I1',date:'2026-10-07',title:'Person Equipment + Military Inventory Foundation',summary:'추상 국가 장비 풀을 Person별 무기/갑옷과 지역별 실물 재고·제작·배급 체계로 전환합니다. 장비 품질의 실제 전투효과와 타일 내부 근·원거리 전투는 I2로 분리합니다.',sections:[['Person 장비',['현역 Person은 weapon/armor 두 슬롯을 가지며 무기가 없으면 생산품이 아닌 임시 곤봉 fallback으로 싸웁니다.','Formation 장비 구성은 실제 memberIds의 장착 장비를 집계합니다.']],['실물 재고·생산',['장비는 supply-node별 정수 재고입니다. 기본 정착지 6, 병영 +12, 무기고 +72 item 저장을 사용합니다.','기초 장비는 목수/건축가, 철제 장비는 실제 Smithy 철공이 Work Order를 수행합니다. 장비 제작 중 해당 Person은 기존 목재/도구 생산을 하지 않습니다.','실제 목재·철·도구는 주문 시작 시 보존적으로 차감되고 작업 완료 때 장비 1개가 재고에 들어옵니다.']],['배급·회수',['현역은 실제로 자국 supply node에 있을 때만 장비를 지급/교체받습니다. 구형 장비는 삭제하지 않고 같은 지역 재고로 회수합니다.','I1에서는 장비 유실/노획/내구도를 아직 넣지 않아 전사·부상·동원해제 장비는 회수 가능한 재고로 되돌립니다.']],['호환 전투력',['H2 전투 공식 자체는 유지합니다. I1 Cohort equipment는 정식 무기 보급률 65% + 갑옷 보급률 35%로 계산합니다.','무기별 melee/ranged/reach/penetration과 갑옷 protection 값은 Registry에 기록하지만 I1 전투에는 아직 사용하지 않습니다.']],['Save Migration',['H2 generic equipmentStock은 legacy weapon+armor kit로 결정적 변환됩니다. 새 게임에서는 legacy 장비를 생산하지 않습니다.','장비 생산+legacy migration = 현재 장착+현재 재고 보존 invariant를 telemetry로 감시합니다.']],['I2로 이월',['OPENING/CONTACT/MELEE, Screen, Reach, 원거리 지원사격, 갑옷 Protection/무기 Penetration, Composite Combat Power는 I2에서 활성화합니다.']]]});

function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const savePrev=NS.SaveSystem;NS.SaveSystem={...savePrev,save(w){localStorage.setItem('village-observer-v0-33i1a1',JSON.stringify(w.serialize()));},load(){const keys=['village-observer-v0-33i1a1','village-observer-v0-33i1a','village-observer-v0-33i1','village-observer-v0-33h2','village-observer-v0-33h1','village-observer-v0-33h','village-observer-v0-33g3a'];let r=null;for(const k of keys)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):savePrev.load?.();},export(w){dl(`village-observer-v033I1A1-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dl(`village-observer-v033I1A1-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){const x=w.telemetry.snapshotsCSV(),c=NS.V032E14?.validateCSV?.(x);if(c&&!c.ok)throw new Error(`CSV schema mismatch: expected ${c.columns} columns; bad rows ${c.bad.slice(0,8).join(', ')}`);dl(`village-observer-v033I1A1-snapshots-${w.telemetry.sessionId}.csv`,'﻿'+x,'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));}};

